    if row.starts_with('+') && !row.starts_with("+++") {
        LineKind::Added
    } else if row.starts_with('-') && !row.starts_with("---") {
        LineKind::Removed
    } else if row.starts_with("@@") {
        LineKind::Hunk
    } else if row.starts_with(' ') {
        LineKind::Context
    } else {
        LineKind::Meta
    }
}

